const fs = require('fs');
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const STATE = '/home/node/.n8n/state';
const REG = STATE + '/registry';
const AN = STATE + '/analytics';
const LOGD = '/home/node/.n8n/logs';

// SYNC-BEGIN: mkdir-collect
const mkdirErrs = [];
for (const d0 of [LOGD, STATE, REG, AN]) {
  try {
    fs.mkdirSync(d0, { recursive: true });
  } catch (e) {
    mkdirErrs.push({ dir: d0,
      error: String((e && e.message) || e).slice(0, 150) });
  }
}
// SYNC-END: mkdir-collect
// best-effort by contract: a transient FS failure must NEVER
// propagate out of log() - this node is a scheduled observer, not a
// gate; a logging crash must not kill the whole tick.
const log = (r) => {
  try {
    fs.appendFileSync(LOGD + '/analytics.jsonl',
      JSON.stringify({ ts: new Date().toISOString(), ...r }) + '\n');
  } catch (e) {}
};
for (const m of mkdirErrs) {
  try { log({ action: 'mkdir-failed', dir: m.dir, error: m.error }); }
  catch (e) {}
}

const token = ENV('TELEGRAM_BOT_TOKEN');
// operator chat_id is pinned config: TELEGRAM_CHAT_ID env first, the
// tg.json written by sp-tg-setup as compat fallback - never learned
// from incoming webhook updates (untrusted source). Same resolution
// order Publish Tick uses.
let chatId = ENV('TELEGRAM_CHAT_ID') || null;
if (!chatId) {
  try { chatId = JSON.parse(fs.readFileSync(STATE + '/tg.json', 'utf8')).chat_id; } catch (e) {}
}
const tg = (method, body) => {
  // SYNC-BEGIN: tg-timeout
  return this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.telegram.org/bot' + token + '/' + method,
    body: body || {},
    json: true,
    // explicit timeout like vkCall below: an unbounded request that
    // hangs on api.telegram.org would stall the whole analytics tick
    timeout: 30000
  });
  // SYNC-END: tg-timeout
};
const http = (o) => this.helpers.httpRequest(o);

// credentials: the VK token file and the env fallback, plus the
// refresh-service shared secret - an httpRequest error can echo the
// request config (the tg() URL embeds the bot token), so every
// configured secret is masked before error text reaches logs.
const ENV_TOKEN = ENV('VK_ACCESS_TOKEN') || null;
const REFRESH_SECRET = ENV('VK_TOKEN_SECRET') || null;
let vkToken = null;
try { vkToken = JSON.parse(fs.readFileSync(STATE + '/vk_token.json', 'utf8')).access_token || null; } catch (e) {}
if (!vkToken) vkToken = ENV_TOKEN;
const SECRET_VALUES = [token, REFRESH_SECRET, vkToken, ENV_TOKEN].filter(Boolean);
// SYNC-BEGIN: scrub-secrets
const scrubSecrets = (s) => {
  let out = String(s);
  for (const v of SECRET_VALUES) {
    if (v && v.length >= 8) out = out.split(v).join('***');
  }
  return out;
};
// SYNC-END: scrub-secrets

// SYNC-BEGIN: write-json-atomic
const writeJsonAtomic = (p, obj) => {
  const tmp = p + '.tmp-' + Date.now().toString(36) +
    Math.random().toString(36).slice(2, 6);
  fs.writeFileSync(tmp, JSON.stringify(obj, null, 2));
  fs.renameSync(tmp, p);
};
// SYNC-END: write-json-atomic

// Host-side refresh: vk_token_service.py extracts a fresh web token
// from the logged-in VK Chrome tab via CDP. The container reaches the
// host through the slirp gateway 10.0.2.2 - same quirk as sp-publish.
const REFRESH_URL = ENV('VK_TOKEN_REFRESH_URL') || 'http://10.0.2.2:8792/vk-token';
const REFRESH_HEADERS = REFRESH_SECRET
  ? { 'X-Shared-Token': REFRESH_SECRET } : {};
// analytics is a read-only observer: the refreshed token is kept in
// memory for this tick only, never written back to vk_token.json -
// sp-publish owns that file (and its 0o600 write contract), and a
// stale read just re-refreshes on the next 6h tick, which is cheap.
async function vkRefresh() {
  const r = await http({ method: 'GET', url: REFRESH_URL, json: true,
    timeout: 60000, headers: REFRESH_HEADERS });
  if (r && r.ok && r.access_token) {
    vkToken = r.access_token;
    if (vkToken && SECRET_VALUES.indexOf(vkToken) === -1) {
      SECRET_VALUES.push(vkToken);
    }
    return true;
  }
  return false;
}

// same transport contract as Publish Tick's vkCall: access_token in
// the POST body (never the URL), explicit 30s timeout, error_code 5
// -> one refresh + one retry. Analytics needs no retryable
// classification - a failure becomes a metrics row, not a requeue.
async function vkCall(method, params) {
  const call = async (t) => http({
    method: 'POST',
    url: 'https://api.vk.com/method/' + method,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: 'v=5.199&access_token=' + encodeURIComponent(t) + '&' + params,
    timeout: 30000,
    json: true
  });
  if (!vkToken) {
    try { await vkRefresh(); }
    catch (e) { log({ action: 'vk-refresh-failed',
      error: scrubSecrets(String((e && e.message) || e)).slice(0, 200) }); }
  }
  if (!vkToken) throw new Error('vk: no token (refresh failed and no env fallback)');
  let res = await call(vkToken);
  if (res && res.error && Number(res.error.error_code) === 5) {
    try { await vkRefresh(); } catch (e) {}
    if (vkToken) res = await call(vkToken);
  }
  return res;
}

// the collector registry: every platform a registry service can name.
// LinkedIn/FB land here when their credentials ship (issues #2/#3) -
// until then a service on an unsupported platform records an
// 'unsupported' metrics row instead of failing the whole tick.
const collectors = {};
collectors.vk = async (ids) => {
  // wall.getById accepts up to 100 posts per call
  const out = {};
  for (let i = 0; i < ids.length; i += 100) {
    const chunk = ids.slice(i, i + 100);
    const res = await vkCall('wall.getById',
      'posts=' + chunk.map(encodeURIComponent).join(','));
    if (res && res.error) {
      for (const id of chunk) {
        out[id] = { status: 'error',
          error: 'vk error ' + res.error.error_code + ': ' +
            scrubSecrets(String(res.error.error_msg || '')).slice(0, 120) };
      }
      continue;
    }
    const items = (res && res.response && res.response.items) ||
      (Array.isArray(res && res.response) ? res.response : []);
    const seen = {};
    for (const it of items) {
      const id = String(it.owner_id) + '_' + String(it.id);
      seen[id] = it.is_deleted
        ? { status: 'gone' }
        : { status: 'measured',
            views: it.views && it.views.count,
            likes: it.likes && it.likes.count,
            comments: it.comments && it.comments.count,
            reposts: it.reposts && it.reposts.count };
    }
    for (const id of chunk) {
      out[id] = seen[id] ||
        { status: 'gone', error: 'not in wall.getById response' };
    }
  }
  return out;
};

// registry fold - same contract as tools/post_report.py: dedup by
// event_id last-occurrence-wins, per post+platform the latest event
// by ts wins stage/status/ts while error/maybe_live are transient
// (cleared when the winning event does not carry them) and
// published_at/external_ids are set-once. Torn lines skip with a
// warning; unknown schema_v folds best-effort.
const foldEvents = () => {
  const posts = {};
  let torn = 0;
  const warnedSv = {};
  let lines = [];
  try {
    lines = fs.readFileSync(REG + '/events.jsonl', 'utf8').split('\n');
  } catch (e) { return { posts: posts, torn: 0, events: 0 }; }
  const deduped = {};
  for (const line of lines) {
    const t = line.trim();
    if (!t) continue;
    let ev = null;
    try { ev = JSON.parse(t); } catch (e) { torn++; continue; }
    if (ev.schema_v !== 1 && !warnedSv[ev.schema_v]) {
      warnedSv[ev.schema_v] = true;
      log({ action: 'schema_v-unexpected', schema_v: ev.schema_v });
    }
    deduped[ev.event_id || JSON.stringify(ev)] = ev;
  }
  const events = Object.values(deduped);
  for (const ev of events) {
    if (!ev.post_id) continue;
    const rec = posts[ev.post_id] ||
      (posts[ev.post_id] = { services: {}, events: [] });
    rec.events.push(ev);
  }
  for (const pid of Object.keys(posts)) {
    const rec = posts[pid];
    rec.events.sort((a, b) =>
      String(a.ts || '').localeCompare(String(b.ts || '')));
    for (const ev of rec.events) {
      const plat = ev.platform || '?';
      const svc = rec.services[plat] ||
        (rec.services[plat] = { platform: plat });
      if (String(svc.ts || '') <= String(ev.ts || '')) {
        for (const k of ['stage', 'status', 'ts', 'error', 'draft_id',
          'maybe_live', 'writer']) {
          if (ev[k] !== undefined && ev[k] !== null) svc[k] = ev[k];
          else if (k === 'error' || k === 'maybe_live') delete svc[k];
        }
      }
      if (ev.published_at && !svc.published_at) {
        svc.published_at = ev.published_at;
      }
      if (Array.isArray(ev.external_ids) && ev.external_ids.length &&
          !svc.external_ids) {
        svc.external_ids = ev.external_ids;
      }
    }
  }
  return { posts: posts, torn: torn, events: events.length };
};

const DIGEST_MS = Math.max(60000,
  parseInt(ENV('ANALYTICS_DIGEST_MS') || '', 10) || 24 * 3600 * 1000);
const WINDOW_DAYS = Math.max(1,
  parseInt(ENV('ANALYTICS_WINDOW_DAYS') || '', 10) || 30);

const out = [];
let tickFailed = false;
try {
  const folded = foldEvents();
  if (folded.torn) {
    log({ action: 'registry-torn-lines', count: folded.torn });
  }
  // measurement candidates: the latest publish-stage verdict is
  // published, OR failed+maybe_live with recovered external_ids (the
  // post may be on the wall - tracking it answers the recovery
  // question for free). test-deleted posts are gone by definition.
  const cands = [];
  for (const pid of Object.keys(folded.posts)) {
    const rec = folded.posts[pid];
    for (const plat of Object.keys(rec.services)) {
      const svc = rec.services[plat];
      const live = svc.stage === 'publish' &&
        (svc.status === 'published' ||
          (svc.status === 'failed' && svc.maybe_live === true));
      if (live && Array.isArray(svc.external_ids) &&
          svc.external_ids.length) {
        cands.push({ post_id: pid, platform: plat,
          external_id: String(svc.external_ids[0]),
          draft_id: svc.draft_id || '',
          published_at: svc.published_at || '',
          maybe_live: svc.maybe_live === true });
      }
    }
  }

  // group by platform, run each platform's collector once
  const byPlat = {};
  for (const c of cands) {
    (byPlat[c.platform] = byPlat[c.platform] || []).push(c);
  }
  const measured = [];
  let errors = 0, unsupported = 0, gone = 0;
  const appendMetric = (row) => {
    try {
      fs.appendFileSync(AN + '/metrics.jsonl',
        JSON.stringify({ schema_v: 1, ts: new Date().toISOString(),
          ...row }) + '\n');
    } catch (e) {
      log({ action: 'metrics-append-failed',
        error: String((e && e.message) || e).slice(0, 150) });
    }
  };
  for (const plat of Object.keys(byPlat)) {
    const group = byPlat[plat];
    const collect = collectors[plat];
    if (!collect) {
      unsupported += group.length;
      for (const c of group) {
        appendMetric({ post_id: c.post_id, platform: plat,
          external_id: c.external_id, status: 'unsupported' });
      }
      continue;
    }
    let result = null;
    try {
      result = await collect(group.map((c) => c.external_id));
    } catch (e) {
      errors += group.length;
      const errStr = scrubSecrets(
        String((e && e.message) || e)).slice(0, 200);
      log({ action: 'collector-failed', platform: plat,
        error: errStr });
      for (const c of group) {
        appendMetric({ post_id: c.post_id, platform: plat,
          external_id: c.external_id, status: 'error',
          error: errStr });
      }
      continue;
    }
    for (const c of group) {
      const m = result[c.external_id] ||
        { status: 'error', error: 'collector returned no row' };
      const row = { post_id: c.post_id, platform: plat,
        external_id: c.external_id, status: m.status };
      if (m.status === 'measured') {
        row.views = m.views; row.likes = m.likes;
        row.comments = m.comments; row.reposts = m.reposts;
        measured.push({ ...c, ...row,
          engagement: (m.likes || 0) + (m.comments || 0) +
            (m.reposts || 0) });
      } else {
        if (m.error) row.error = m.error;
        if (m.status === 'gone') gone++; else errors++;
      }
      appendMetric(row);
    }
  }

  // feedback signal for content-gen accents (issue #8): top posts by
  // engagement inside the sliding window. perf_summary.json is the
  // artifact; the content-gen read side lands in a later iteration.
  const winCut = Date.now() - WINDOW_DAYS * 86400000;
  const top = measured
    .filter((m) => !m.published_at ||
      Date.parse(m.published_at) >= winCut)
    .sort((a, b) => (b.engagement - a.engagement) ||
      ((b.views || 0) - (a.views || 0)));
  try {
    writeJsonAtomic(AN + '/perf_summary.json', {
      schema_v: 1,
      generated_at: new Date().toISOString(),
      window_days: WINDOW_DAYS,
      posts: top.slice(0, 20).map((m) => ({
        post_id: m.post_id, platform: m.platform,
        external_id: m.external_id, published_at: m.published_at,
        views: m.views, likes: m.likes, comments: m.comments,
        reposts: m.reposts, engagement: m.engagement }))
    });
  } catch (e) {
    log({ action: 'perf-summary-failed',
      error: String((e && e.message) || e).slice(0, 150) });
  }

  // periodic digest to the operator chat: gated by the cursor so the
  // 6h tick collects but only one digest per DIGEST_MS goes out. The
  // cursor advances ONLY on a confirmed send - a tg() failure keeps
  // the digest due so the next tick retries instead of dropping it.
  let digestSent = false;
  let cursor = null;
  try { cursor = JSON.parse(fs.readFileSync(AN + '/digest_cursor.json', 'utf8')); } catch (e) {}
  const digestDue = !cursor || !cursor.ts ||
    (Date.now() - Date.parse(cursor.ts)) >= DIGEST_MS;
  if (digestDue && measured.length && chatId) {
    const lines = top.slice(0, 10).map((m, i) =>
      (i + 1) + '. ' + m.post_id + ' [' + m.platform + ' ' +
      m.external_id + '] views ' + (m.views == null ? '?' : m.views) +
      ' | likes ' + (m.likes == null ? '?' : m.likes) +
      ' | comments ' + (m.comments == null ? '?' : m.comments) +
      ' | reposts ' + (m.reposts == null ? '?' : m.reposts) +
      (m.published_at ? ' (' + String(m.published_at).slice(0, 10) + ')' : ''));
    const text = 'post performance digest (top ' + lines.length +
      ' by engagement, ' + WINDOW_DAYS + 'd window):\n' +
      lines.join('\n') +
      '\n\nmeasured ' + measured.length +
      ', gone ' + gone + ', errors ' + errors +
      ', unsupported ' + unsupported;
    const r = await tg('sendMessage',
      { chat_id: chatId, text: text.slice(0, 4000) });
    if (r && r.ok) {
      digestSent = true;
      try {
        writeJsonAtomic(AN + '/digest_cursor.json',
          { ts: new Date().toISOString() });
      } catch (e) {
        log({ action: 'digest-cursor-failed',
          error: String((e && e.message) || e).slice(0, 150) });
      }
    } else {
      log({ action: 'digest-send-failed',
        error: scrubSecrets(JSON.stringify(r || null)).slice(0, 200) });
    }
  }
  try {
    writeJsonAtomic(AN + '/status.json', {
      ts: new Date().toISOString(), candidates: cands.length,
      measured: measured.length, gone: gone, errors: errors,
      unsupported: unsupported, digest_sent: digestSent });
  } catch (e) {}
  out.push('analytics tick: ' + cands.length + ' candidates, ' +
    measured.length + ' measured, ' + gone + ' gone, ' + errors +
    ' errors, ' + unsupported + ' unsupported, digest ' +
    (digestSent ? 'sent' : (digestDue ? 'due-but-empty' : 'not-due')));
} catch (e) {
  tickFailed = true;
  log({ action: 'tick-failed',
    error: scrubSecrets(String((e && e.message) || e)).slice(0, 300) });
  out.push('analytics tick FAILED: ' +
    scrubSecrets(String((e && e.message) || e)).slice(0, 200));
}
log({ action: 'tick-done', summary: out.join(' | '),
  failed: tickFailed });
return [{ json: { ok: !tickFailed, summary: out.join(' | ') } }];
